python3 -c "
import requests

# Try NWS API for flood stage info
# First, let's try the NWPS (National Water Prediction Service) API
resp = requests.get('https://api.water.noaa.gov/nwps/v1/gauges', params={
    'stype': 'usgs',
}, timeout=30, headers={'Accept': 'application/json'})
print('NWPS status:', resp.status_code)
print('Content type:', resp.headers.get('content-type'))
if resp.status_code == 200:
    data = resp.json()
    print('Keys:', list(data.keys()) if isinstance(data, dict) else type(data))
    if isinstance(data, list):
        print('Count:', len(data))
        print('First:', data[0] if data else 'empty')
    elif isinstance(data, dict):
        for k in list(data.keys())[:5]:
            v = data[k]
            if isinstance(v, list):
                print(f'{k}: list of {len(v)} items')
                if v: print(f'  first: {v[0]}')
            else:
                print(f'{k}: {v}')
" 2>&1 | head -40

